CREATE TABLE IF NOT EXISTS terminal_role_incomes (server_id BIGINT NOT NULL,player_id BIGINT NOT NULL,account_id BIGINT NOT NULL,id VARCHAR(128) NOT NULL,label VARCHAR(255) CHARACTER SET utf8mb4 NOT NULL,amount_cents BIGINT NOT NULL,created_at BIGINT NOT NULL,revision BIGINT NOT NULL,source VARCHAR(24) NOT NULL,PRIMARY KEY(server_id,player_id,id),KEY terminal_role_income_revision(server_id,player_id,revision),KEY idx_terminal_role_incomes_account_id(account_id)) ENGINE=InnoDB;
